import{_ as t,o as r,c as a,a5 as o}from"./chunks/framework.UjrY2eRK.js";const p=JSON.parse('{"title":"Issue 27: provider, container, and release-gate research","description":"","frontmatter":{},"headers":[],"relativePath":"research/issue-27-provider-container-release-gates.md","filePath":"research/issue-27-provider-container-release-gates.md","lastUpdated":1788169631000}'),i={name:"research/issue-27-provider-container-release-gates.md"};function n(s,e,d,l,c,h){return r(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="issue-27-provider-container-and-release-gate-research" tabindex="-1">Issue 27: provider, container, and release-gate research <a class="header-anchor" href="#issue-27-provider-container-and-release-gate-research" aria-label="Permalink to &quot;Issue 27: provider, container, and release-gate research&quot;">​</a></h1><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><p>Keep three distinct OIDC test layers and make their required contexts explicit:</p><ol><li>Run the pinned local <code>oidc-provider@9.11.3</code> suite on every pull request that affects authentication or the Bun gateway. It is deterministic, requires no external service or secret, and is the fast protocol contract.</li><li>Run a pinned Pocket ID container suite on authentication-changing pull requests, the final integration pull request, and weekly on <code>master</code>.</li><li>Run a pinned Authentik server, worker, and PostgreSQL suite weekly, on manual request, on the final integration pull request, and on every pull request to <code>master</code> that can become a release. This includes a Release Please pull request before it is merged.</li></ol><p>Both real-provider suites must pass before the first production release. They must provision disposable users, groups, applications, clients, and secrets at run time; no long-lived provider credential belongs in GitHub. A final stable required check should aggregate the path-classification and provider results so branch protection does not depend on dynamically absent job names.</p><p>The production image should use a Node/pnpm builder for the Angular application, a Bun builder for the gateway, and a minimal Bun runtime stage containing only the runtime bundles, browser assets, and gateway plus administration migrations. The assembled image—not the Dockerfile text—is the release artifact to inspect and exercise.</p><p>This decision implements the provider and release portions of <a href="https://github.com/quwisky/trinity-push-gateway/issues/27" target="_blank" rel="noreferrer">#27</a>. It retains the OIDC selection and deterministic harness already recorded in <code>docs/research/issue-22-oidc-session-selection.md</code>; it does not reopen that selection.</p><h2 id="repository-baseline" tabindex="-1">Repository baseline <a class="header-anchor" href="#repository-baseline" aria-label="Permalink to &quot;Repository baseline&quot;">​</a></h2><p>At the time of this research:</p><ul><li><code>apps/push-gateway/scripts/test-oidc-provider.mjs</code> already starts exact <code>oidc-provider@9.11.3</code> in a Node child on a loopback ephemeral port. Its two profiles reproduce Pocket ID&#39;s <code>groups</code> scope plus <code>client_secret_basic</code> and Authentik&#39;s profile-mapped <code>groups</code> plus <code>client_secret_post</code>.</li><li><code>apps/push-gateway/test/bun/auth/support/test-oidc-provider.ts</code> drives that child from Bun, owns cookies and redirects, and terminates it after the test.</li><li><code>.github/workflows/ci.yml</code> handles affected Nx checks and Release Please; <code>.github/workflows/container.yml</code> builds and smokes the image, including the compressed 150 MiB guard.</li><li>The current image is non-root and its Compose service already uses a read-only root filesystem, drops capabilities, binds to loopback, and persists <code>/data</code>. Issue #27 still needs the Angular browser assets, administration migrations, full final-image inspection, and provider/container integration gates.</li></ul><p>These are repository observations, not claims about the external products.</p><h2 id="gate-matrix" tabindex="-1">Gate matrix <a class="header-anchor" href="#gate-matrix" aria-label="Permalink to &quot;Gate matrix&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Gate</th><th>Pull request</th><th>Scheduled</th><th>Manual</th><th>Release consequence</th></tr></thead><tbody><tr><td>Deterministic <code>oidc-provider</code></td><td>Authentication or Bun-gateway affected; always on final integration PR</td><td>Optional redundancy</td><td>Useful for diagnosis</td><td>Required wherever selected by the path classifier</td></tr><tr><td>Pocket ID</td><td>Authentication-changing PRs and final integration PR</td><td>Weekly on <code>master</code></td><td>Optional</td><td>Must be green before first production release</td></tr><tr><td>Authentik</td><td>Final integration PR and every release-capable PR to <code>master</code></td><td>Weekly on <code>master</code></td><td>Provider-selectable trusted ref</td><td>Must be green on the Release Please PR before merge and before first production release</td></tr><tr><td>Assembled container</td><td>Container/gateway/UI affected PRs and release-capable PRs</td><td>Exercise as part of both live-provider suites</td><td>Provider-selectable</td><td>Size, contents, hardening, routes, and delivery must all pass</td></tr><tr><td>Aggregate <code>release-gates</code></td><td>Always present</td><td>Always present</td><td>Always present</td><td>Branch-protection status; succeeds only when every selected gate succeeded</td></tr></tbody></table><p>Running Authentik on all release-capable pull requests to <code>master</code> is less brittle than identifying Release Please from a mutable title or branch name. If CI later narrows this condition, it must use trusted repository metadata and changed release files, not title text alone.</p><p>The current gateway accepts non-TLS OIDC issuers only on loopback. Therefore, the Linux CI topology must either give the assembled gateway container access to the provider&#39;s host-loopback port for this test only, or terminate TLS at a shared hostname. A plain <code>http://pocket-id:port</code> or <code>http://authentik-server:port</code> Compose alias would test a configuration the gateway correctly rejects; the provider, browser, and gateway must all observe the same exact issuer.</p><p>GitHub scheduled workflows only run from the latest commit on the default branch, and the workflow file must exist there. A weekly schedule therefore validates <code>master</code>, not a still-unmerged integration branch (<a href="https://docs.github.com/en/actions/reference/workflows-and-actions/events-that-trigger-workflows#schedule" target="_blank" rel="noreferrer">GitHub Actions event documentation</a>). Use a non-hour-boundary UTC minute because GitHub warns that scheduled jobs can be delayed or dropped during high load, especially at the start of an hour (<a href="https://docs.github.com/en/actions/reference/workflows-and-actions/events-that-trigger-workflows#schedule" target="_blank" rel="noreferrer">GitHub Actions event documentation</a>).</p><h2 id="deterministic-local-oidc-provider" tabindex="-1">Deterministic local OIDC provider <a class="header-anchor" href="#deterministic-local-oidc-provider" aria-label="Permalink to &quot;Deterministic local OIDC provider&quot;">​</a></h2><h3 id="retained-setup" tabindex="-1">Retained setup <a class="header-anchor" href="#retained-setup" aria-label="Permalink to &quot;Retained setup&quot;">​</a></h3><p>Retain the exact, development-only <code>oidc-provider@9.11.3</code> dependency and its Node 24 child-process boundary. The tagged package documents Node as its runtime, while the maintainer explicitly does not claim Bun support (<a href="https://github.com/panva/node-oidc-provider/tree/v9.11.3" target="_blank" rel="noreferrer">v9.11.3 source</a>, <a href="https://github.com/panva/node-oidc-provider/discussions/1250" target="_blank" rel="noreferrer">maintainer runtime answer</a>). Driving the Node process from Bun tests keeps the gateway under its production runtime without depending on an unsupported provider runtime.</p><p>The harness should own all nondeterminism:</p><ul><li>listen on <code>127.0.0.1</code> with port <code>0</code>, then communicate the resolved issuer to the Bun parent through its existing structured startup line;</li><li>use fixed account subjects, emails, groups, client IDs, redirect paths, and provider profiles;</li><li>use a fixed test clock or explicit expiry offsets, isolated in-memory provider state, no outbound network access, and no environment-derived user identity;</li><li>wait for the child startup contract before discovery, fail with captured child diagnostics, and always terminate and reap the child;</li><li>cover success, missing group, wrong group, missing profile claim, callback replay, wrong state/nonce/issuer/audience, provider failure, and both client authentication methods.</li></ul><p>The provider&#39;s configuration surface is explicitly application-owned, so the harness must pin every behavior on which the gateway relies rather than inherit changing defaults (<a href="https://github.com/panva/node-oidc-provider/blob/v9.11.3/docs/README.md" target="_blank" rel="noreferrer">v9.11.3 configuration documentation</a>).</p><p>Expose this suite as a named Nx target or a clearly named subset of the existing Bun check. CI should classify changes to the authentication module, Bun adapter, OIDC configuration/schema, migrations, provider harness, package lock, and its own workflow as affected. This suite is the portable protocol baseline; it is not evidence that either real provider still interoperates.</p><h2 id="pocket-id-gate" tabindex="-1">Pocket ID gate <a class="header-anchor" href="#pocket-id-gate" aria-label="Permalink to &quot;Pocket ID gate&quot;">​</a></h2><h3 id="pinned-topology-and-readiness" tabindex="-1">Pinned topology and readiness <a class="header-anchor" href="#pinned-topology-and-readiness" aria-label="Permalink to &quot;Pinned topology and readiness&quot;">​</a></h3><p>Pin the Pocket ID image to the intended release tag and immutable digest. The release current for this research is <code>v2.14.0</code> (<a href="https://github.com/pocket-id/pocket-id/releases/tag/v2.14.0" target="_blank" rel="noreferrer">Pocket ID v2.14.0 release</a>). Run one disposable container with a temporary data volume and these test-only settings:</p><ul><li>a canonical <code>APP_URL</code> matching the issuer used by the gateway;</li><li>generated <code>ENCRYPTION_KEY_FILE</code> and <code>STATIC_API_KEY</code> values;</li><li><code>ANALYTICS_DISABLED=true</code> and <code>VERSION_CHECK_DISABLED=true</code> so the gate does not depend on optional external calls;</li><li>the documented UID/GID defaults of 1000 unless the test deliberately probes ownership.</li></ul><p>Pocket ID documents <code>APP_URL</code>, file-backed encryption keys, static API keys, UID/GID configuration, and the two offline switches in its environment reference (<a href="https://pocket-id.org/docs/configuration/environment-variables" target="_blank" rel="noreferrer">Pocket ID environment variables</a>). Its official Compose example invokes <code>/app/pocket-id healthcheck</code> (<a href="https://raw.githubusercontent.com/pocket-id/pocket-id/v2.14.0/docker-compose.yml" target="_blank" rel="noreferrer">official tagged Compose file</a>), and the tagged healthcheck implementation probes <code>/healthz</code> (<a href="https://github.com/pocket-id/pocket-id/blob/v2.14.0/backend/internal/cmds/healthcheck.go" target="_blank" rel="noreferrer">healthcheck command</a>). Because <code>/healthz</code> is a liveness response rather than proof that the configured issuer and OIDC endpoints work (<a href="https://github.com/pocket-id/pocket-id/blob/v2.14.0/backend/internal/controller/healthz_controller.go" target="_blank" rel="noreferrer">health endpoint</a>), the gate must wait for Docker health and then fetch discovery, validate its exact issuer, and confirm the authorization, token, JWKS, and end-session endpoints before provisioning users.</p><h3 id="declarative-test-data" tabindex="-1">Declarative test data <a class="header-anchor" href="#declarative-test-data" aria-label="Permalink to &quot;Declarative test data&quot;">​</a></h3><p>Use the static API key only inside the ephemeral runner to create:</p><ol><li>an allowed group with a unique fixed test name;</li><li>one user in that group and one user outside it;</li><li>one confidential authorization-code client with the gateway&#39;s exact callback URI and PKCE flow;</li><li>a restriction from that client to the allowed group;</li><li>one client secret, captured once and immediately masked;</li><li>one-time access tokens for the two test users so browser automation does not require a human passkey.</li></ol><p>Pocket ID&#39;s tagged routes expose OIDC client creation, secret creation, and allowed-group updates (<a href="https://github.com/pocket-id/pocket-id/blob/v2.14.0/backend/internal/controller/oidc_controller.go" target="_blank" rel="noreferrer">OIDC client controller</a>, <a href="https://github.com/pocket-id/pocket-id/blob/v2.14.0/backend/internal/dto/oidc_dto.go" target="_blank" rel="noreferrer">OIDC DTOs</a>). The official allowed-groups guide says a newly created OIDC client allows no users until it is explicitly unrestricted or assigned one or more allowed groups; this gate must assign only the operator group (<a href="https://pocket-id.org/docs/configuration/allowed-groups" target="_blank" rel="noreferrer">allowed groups</a>). The tagged source authenticates the API through <code>X-API-Key</code> (<a href="https://github.com/pocket-id/pocket-id/blob/v2.14.0/backend/internal/middleware/api_key_auth.go" target="_blank" rel="noreferrer">API-key middleware</a>) and implements one-time login tokens for unattended access (<a href="https://github.com/pocket-id/pocket-id/blob/v2.14.0/backend/internal/onetimeaccess/handler.go" target="_blank" rel="noreferrer">one-time access handler</a>).</p><p>Configure the gateway with scopes <code>openid profile email groups</code>, group claim <code>groups</code>, the exact required group, and <code>client_secret_basic</code>. Pocket ID&#39;s official client-authentication guide specifies confidential clients with a client ID and secret (<a href="https://pocket-id.org/docs/guides/oidc-client-authentication" target="_blank" rel="noreferrer">client authentication</a>), and the tagged claim service emits an array of group names only when the <code>groups</code> scope is requested (<a href="https://github.com/pocket-id/pocket-id/blob/v2.14.0/backend/internal/oidc/claims_service.go" target="_blank" rel="noreferrer">claim service</a>).</p><p>The gate must prove successful login, rejection of the non-member, local-first logout/session revocation, provider-outage isolation, and that Matrix delivery plus public health remain available while authentication fails. It must also exercise the administration root and one deep link through the assembled image.</p><h2 id="authentik-gate" tabindex="-1">Authentik gate <a class="header-anchor" href="#authentik-gate" aria-label="Permalink to &quot;Authentik gate&quot;">​</a></h2><h3 id="pinned-topology-and-readiness-1" tabindex="-1">Pinned topology and readiness <a class="header-anchor" href="#pinned-topology-and-readiness-1" aria-label="Permalink to &quot;Pinned topology and readiness&quot;">​</a></h3><p>Pin Authentik server and worker images to the intended release tag and immutable digest; use a matching PostgreSQL service. The release current for this research is <code>2026.8.0</code> (<a href="https://github.com/goauthentik/authentik/releases/tag/version/2026.8.0" target="_blank" rel="noreferrer">Authentik 2026.8.0 release</a>). The official Docker Compose installation comprises server and worker services with PostgreSQL (<a href="https://docs.goauthentik.io/install-config/install/docker-compose" target="_blank" rel="noreferrer">Docker Compose installation</a>, <a href="https://docs.goauthentik.io/compose.yml" target="_blank" rel="noreferrer">official Compose file</a>).</p><p>Generate and mask the Authentik secret key, PostgreSQL password, bootstrap token, test-user credential, and OAuth client secret at run time. Wait for:</p><ol><li>PostgreSQL health;</li><li>the server and worker container health states;</li><li>server <code>/-/health/ready/</code> returning success;</li><li>discovery at the per-provider issuer returning the exact configured issuer and usable endpoints.</li></ol><p>Authentik documents <code>/-/health/live/</code> as the running-process probe, <code>/-/health/ready/</code> as including PostgreSQL connectivity, and <code>ak healthcheck</code> for the worker (<a href="https://docs.goauthentik.io/sys-mgmt/ops/monitoring" target="_blank" rel="noreferrer">Authentik monitoring</a>). Its image is built with UID 1000 and a built-in <code>ak healthcheck</code> (<a href="https://github.com/goauthentik/authentik/blob/version%2F2026.8.0/lifecycle/container/Dockerfile" target="_blank" rel="noreferrer">tagged container Dockerfile</a>). Container health alone is therefore insufficient OIDC readiness; discovery and issuer validation remain a separate gate step.</p><h3 id="blueprint-and-oidc-data" tabindex="-1">Blueprint and OIDC data <a class="header-anchor" href="#blueprint-and-oidc-data" aria-label="Permalink to &quot;Blueprint and OIDC data&quot;">​</a></h3><p>Prefer a generated, runner-temporary Authentik blueprint. Create:</p><ul><li>the allowed group;</li><li>an allowed user and a disallowed user;</li><li>an OAuth2/OIDC provider using a confidential client, authorization code, PKCE, exact callback URI, per-provider issuer, and explicit <code>include_claims_in_id_token: true</code>;</li><li>an application associated with that provider;</li><li>the built-in <code>openid</code>, <code>profile</code>, and <code>email</code> scope mappings.</li></ul><p>Authentik applies blueprints from mounted blueprint directories and treats a blueprint transaction atomically (<a href="https://docs.goauthentik.io/customize/blueprints/" target="_blank" rel="noreferrer">blueprints</a>). Blueprint version 1 supports model entries and references through <code>!KeyOf</code> and <code>!Find</code> (<a href="https://docs.goauthentik.io/customize/blueprints/v1/structure/" target="_blank" rel="noreferrer">blueprint structure</a>), while <code>!Env</code> and <code>!File</code> allow the generated secret values to stay out of the committed blueprint (<a href="https://docs.goauthentik.io/customize/blueprints/v1/tags/" target="_blank" rel="noreferrer">blueprint tags</a>). If API provisioning is easier to maintain, use an ephemeral <code>AUTHENTIK_BOOTSTRAP_TOKEN</code>; Authentik documents that the token initializes the <code>akadmin</code> account only during first startup (<a href="https://docs.goauthentik.io/install-config/automated-install/" target="_blank" rel="noreferrer">automated install</a>).</p><p>Authentik documents that an application is associated with an authentication provider, normally one-to-one (<a href="https://docs.goauthentik.io/add-secure-apps/providers/" target="_blank" rel="noreferrer">applications and providers</a>). Its OAuth2/OIDC provider supports authorization code, confidential client credentials, PKCE, and a per-provider issuer rooted at <code>/application/o/&lt;slug&gt;/</code> (<a href="https://docs.goauthentik.io/add-secure-apps/providers/oauth2/" target="_blank" rel="noreferrer">OAuth2/OIDC provider</a>). OAuth scope mappings add custom claims to tokens (<a href="https://docs.goauthentik.io/add-secure-apps/providers/property-mappings/" target="_blank" rel="noreferrer">property mappings</a>), and the tagged default profile mapping emits <code>groups</code> as the user&#39;s group-name array (<a href="https://github.com/goauthentik/authentik/blob/version%2F2026.8.0/blueprints/system/providers-oauth2.yaml" target="_blank" rel="noreferrer">default OAuth mappings</a>). The tagged provider model includes an <code>include_claims_in_id_token</code> setting; making it explicit ensures the gateway receives the mapped <code>groups</code> claim in the ID token instead of depending on a provider default (<a href="https://github.com/goauthentik/authentik/blob/version%2F2026.8.0/authentik/providers/oauth2/models.py" target="_blank" rel="noreferrer">OAuth2 provider model</a>).</p><p>Configure the gateway with <code>openid profile email</code>, group claim <code>groups</code>, the exact required group, and <code>client_secret_post</code>. Prove full browser login for the member, group rejection, logout/local revocation, provider outage, and the same assembled-image Matrix/health isolation checks as Pocket ID. Authentik&#39;s greater startup cost is why it belongs in weekly, manual, integration, and pre-release gates rather than every authentication implementation iteration.</p><h2 id="production-container-contract" tabindex="-1">Production container contract <a class="header-anchor" href="#production-container-contract" aria-label="Permalink to &quot;Production container contract&quot;">​</a></h2><p>Docker recommends multi-stage builds so a final stage can copy only the artifacts required at runtime and leave build tools behind (<a href="https://docs.docker.com/build/building/multi-stage/" target="_blank" rel="noreferrer">multi-stage builds</a>, <a href="https://docs.docker.com/build/building/best-practices/#use-multi-stage-builds" target="_blank" rel="noreferrer">build best practices</a>). Bun&#39;s official Docker guide likewise separates dependency installation, production dependencies, build, and release stages (<a href="https://bun.com/guides/ecosystem/docker" target="_blank" rel="noreferrer">Bun Docker guide</a>).</p><p>Use this stage contract:</p><ol><li><strong>UI builder:</strong> pinned Node and pnpm install from the frozen root lockfile, then the Nx production build for <code>push-gateway-ui</code>.</li><li><strong>Gateway builder:</strong> pinned Bun stage consuming the frozen pnpm dependency tree, then bundle the Bun entry with production minification and explicit source maps disabled.</li><li><strong>Runtime:</strong> pinned minimal Bun base, copying only Bun runtime bundles, UI browser output, gateway migrations, administration migrations, and any indispensable runtime metadata.</li></ol><p>When a Bun application needs a runtime dependency tree, <code>bun install --production</code> omits development dependencies and <code>--frozen-lockfile</code> refuses lockfile drift (<a href="https://bun.com/docs/pm/cli/install" target="_blank" rel="noreferrer">Bun install</a>). This gateway is bundled, so the stronger final-stage rule is to copy no <code>node_modules</code> at all; the root pnpm install remains the single frozen-lockfile dependency installation. Bun documents <code>none</code> as the source-map mode that emits no source map; make that choice explicit in the build and inspect the final filesystem for <code>*.map</code> (<a href="https://bun.com/docs/bundler#sourcemap" target="_blank" rel="noreferrer">Bun sourcemaps</a>). <code>.dockerignore</code> reduces build context but does not prove that generated source maps or development packages were not copied, so artifact inspection remains mandatory (<a href="https://docs.docker.com/build/building/best-practices/#exclude-with-dockerignore" target="_blank" rel="noreferrer">Docker <code>.dockerignore</code> guidance</a>).</p><p>The final-image contract check must fail if it finds <code>node</code>, <code>npm</code>, <code>pnpm</code>, <code>node_modules</code>, package-manager caches, source trees, TypeScript, source maps, test fixtures, provider harnesses, or development-only dependencies. It must also prove that both migration sets and all hashed browser assets exist and that the compressed AMD64 image is at most 150 MiB. Keep the existing Worker bundle ceiling and Angular initial/chunk budgets as independent gates; image size cannot substitute for either.</p><p>Set the image user and group to numeric 1000 and inspect the built image&#39;s <code>Config.User</code>. Docker recommends switching to a non-root <code>USER</code> when the service does not need privileges (<a href="https://docs.docker.com/build/building/best-practices/#user" target="_blank" rel="noreferrer">Docker <code>USER</code> best practice</a>, <a href="https://docs.docker.com/reference/dockerfile/#user" target="_blank" rel="noreferrer">Dockerfile <code>USER</code></a>). Run the assembled image with:</p><ul><li><code>--read-only</code> / Compose <code>read_only: true</code>;</li><li>every Linux capability dropped and <code>no-new-privileges</code> enabled;</li><li>only <code>/data</code> as a persistent writable volume;</li><li>tmpfs mounts only for required ephemeral paths;</li><li>loopback-only publication in the supplied Compose example.</li></ul><p>Docker&#39;s read-only flag prevents writes to the container root filesystem (<a href="https://docs.docker.com/reference/cli/docker/container/run/#read-only" target="_blank" rel="noreferrer"><code>docker run --read-only</code></a>); Compose separately defines <code>read_only</code>, <code>cap_drop</code>, and <code>tmpfs</code> (<a href="https://docs.docker.com/reference/compose-file/services/#read_only" target="_blank" rel="noreferrer">Compose <code>read_only</code></a>, <a href="https://docs.docker.com/reference/compose-file/services/#cap_drop" target="_blank" rel="noreferrer">Compose <code>cap_drop</code></a>, <a href="https://docs.docker.com/reference/compose-file/services/#tmpfs" target="_blank" rel="noreferrer">Compose <code>tmpfs</code></a>). Docker volumes are the persistent-data mechanism, so the gate must verify that database, backup, and cleanup writes remain under <code>/data</code> (<a href="https://docs.docker.com/engine/storage/volumes/" target="_blank" rel="noreferrer">Docker volumes</a>).</p><p>The runtime healthcheck must use a utility present in the final image and prove public gateway readiness. Docker uses healthcheck exit status to mark the container <code>starting</code>, <code>healthy</code>, or <code>unhealthy</code>; it does not restart the container by itself (<a href="https://docs.docker.com/reference/dockerfile/#healthcheck" target="_blank" rel="noreferrer">Dockerfile <code>HEALTHCHECK</code></a>). The smoke suite must therefore wait explicitly for healthy and retain logs on failure without publishing secrets.</p><h2 id="github-actions-and-secret-handling" tabindex="-1">GitHub Actions and secret handling <a class="header-anchor" href="#github-actions-and-secret-handling" aria-label="Permalink to &quot;GitHub Actions and secret handling&quot;">​</a></h2><p>Add a dedicated provider workflow or reusable provider jobs with <code>pull_request</code>, <code>schedule</code>, and <code>workflow_dispatch</code> entry points. GitHub only accepts <code>workflow_dispatch</code> for a workflow present on the default branch, and a manual run can target a selected ref (<a href="https://docs.github.com/en/actions/reference/workflows-and-actions/events-that-trigger-workflows#workflow_dispatch" target="_blank" rel="noreferrer">GitHub Actions event documentation</a>). Use a typed manual input such as <code>provider: pocket-id | authentik | all</code>, record the tested SHA in the summary, and accept only repository-owned refs for any future job that receives privileged credentials.</p><p>The provider gates described here need no repository or environment secret:</p><ul><li>generate high-entropy credentials inside the job;</li><li>immediately emit <code>::add-mask::&lt;value&gt;</code> for each generated value;</li><li>put configuration and secret files under <code>$RUNNER_TEMP</code> with mode <code>0600</code>;</li><li>pass secrets through environment variables or standard input, never command arguments or workflow output;</li><li>clean containers, volumes, networks, and temporary files in an <code>always()</code> step;</li><li>never upload provider databases, generated configuration, browser storage, raw container logs, or HTTP traces as artifacts.</li></ul><p>GitHub recommends masking sensitive values that are not registered as Actions secrets and avoiding command-line secret passing (<a href="https://docs.github.com/en/actions/how-tos/write-workflows/choose-what-workflows-do/use-secrets" target="_blank" rel="noreferrer">using secrets in Actions</a>). It also warns that structured secret blobs can defeat exact redaction, so keep each credential a separate masked scalar (<a href="https://docs.github.com/en/actions/reference/security/secrets" target="_blank" rel="noreferrer">Actions secrets reference</a>).</p><p>If a future live external provider genuinely requires durable credentials, place them in a protected <code>provider-release</code> environment and reference that environment only from a trusted default-branch/manual job. Environment secrets become available only to a job that references the environment and, when protection is configured, only after its rules pass (<a href="https://docs.github.com/en/actions/reference/workflows-and-actions/deployments-and-environments" target="_blank" rel="noreferrer">deployment environments</a>). Normal secrets are not passed to fork pull requests or Dependabot-triggered workflows, and reusable workflows do not receive them automatically (<a href="https://docs.github.com/en/actions/how-tos/write-workflows/choose-what-workflows-do/use-secrets" target="_blank" rel="noreferrer">using secrets in Actions</a>).</p><p>Never use <code>pull_request_target</code> to build or execute pull-request code with an elevated token or provider secret. GitHub&#39;s security guidance identifies that combination as unsafe because untrusted pull-request code can obtain the privileged context (<a href="https://docs.github.com/en/actions/reference/security/securely-using-pull_request_target" target="_blank" rel="noreferrer">secure <code>pull_request_target</code> use</a>). The normal <code>pull_request</code> event plus disposable local providers is sufficient for this design.</p><h2 id="implementation-checklist" tabindex="-1">Implementation checklist <a class="header-anchor" href="#implementation-checklist" aria-label="Permalink to &quot;Implementation checklist&quot;">​</a></h2><h3 id="workflow-and-classification" tabindex="-1">Workflow and classification <a class="header-anchor" href="#workflow-and-classification" aria-label="Permalink to &quot;Workflow and classification&quot;">​</a></h3><ul><li>[ ] Add one path classifier covering authentication source, Bun source, migrations, UI/browser source, Docker/Compose, lockfile, provider scripts, and the workflow itself.</li><li>[ ] Expose the deterministic provider suite as a named Nx target and select it for authentication/Bun changes.</li><li>[ ] Add pinned-by-digest Pocket ID and Authentik provider jobs with isolated names, networks, volumes, and per-run credentials.</li><li>[ ] Add weekly <code>master</code> schedule at an off-minute and a typed <code>workflow_dispatch</code> provider selector.</li><li>[ ] Run Pocket ID on authentication-changing and final integration pull requests; run Authentik on final integration and all release-capable pull requests to <code>master</code>.</li><li>[ ] Add an always-present <code>release-gates</code> aggregation job suitable for branch protection. Treat only deliberately skipped, non-selected jobs as success.</li><li>[ ] Keep Release Please as the only version/changelog writer; provider and image gates only validate its pull request.</li></ul><h3 id="provider-provisioning" tabindex="-1">Provider provisioning <a class="header-anchor" href="#provider-provisioning" aria-label="Permalink to &quot;Provider provisioning&quot;">​</a></h3><ul><li>[ ] Pin Node, Bun, <code>oidc-provider</code>, both provider images, PostgreSQL, and every browser used by the gate.</li><li>[ ] Reuse the existing Node-child deterministic harness; eliminate wall-clock, port, account, and cleanup races.</li><li>[ ] Provision Pocket ID group, two users, confidential client, exact callback, group restriction, one-time login tokens, and one generated client secret whose value is captured once.</li><li>[ ] Require Pocket ID Docker health plus exact discovery/issuer readiness.</li><li>[ ] Provision Authentik through a generated blueprint or ephemeral bootstrap API: group, two users, provider, application, callback, mappings, and explicit ID-token claim inclusion.</li><li>[ ] Require PostgreSQL, server, and worker health plus Authentik readiness and exact discovery/issuer checks.</li><li>[ ] Prove successful and rejected group flows, local-first logout, provider outage isolation, and no provider token persistence for both products.</li></ul><h3 id="assembled-image" tabindex="-1">Assembled image <a class="header-anchor" href="#assembled-image" aria-label="Permalink to &quot;Assembled image&quot;">​</a></h3><ul><li>[ ] Add the Node/pnpm UI build stage and Bun production build stage.</li><li>[ ] Copy only runtime bundles, browser assets, and both migration sets to the final Bun stage; explicitly disable source maps.</li><li>[ ] Inspect the final filesystem for forbidden tools, sources, maps, development dependencies, and provider test code.</li><li>[ ] Inspect numeric UID/GID 1000 and execute with read-only root, all capabilities dropped, no-new-privileges, and <code>/data</code> as the only persistent writable location.</li><li>[ ] Retain the 150 MiB compressed AMD64 ceiling, Worker bundle ceiling, and Angular browser budgets as separate failures.</li><li>[ ] Smoke public health, Matrix notification delivery, disabled/invalid admin behavior, admin root, deep link, assets, headers, 404/405 behavior, and both real OIDC logins from the assembled image.</li><li>[ ] Exercise backup, cleanup, metrics-writer failure, and disabled/enabled benchmark paths under Matrix load; investigate sustained p95 regressions over issue #27&#39;s five-percent threshold.</li></ul><h3 id="secret-and-evidence-hygiene" tabindex="-1">Secret and evidence hygiene <a class="header-anchor" href="#secret-and-evidence-hygiene" aria-label="Permalink to &quot;Secret and evidence hygiene&quot;">​</a></h3><ul><li>[ ] Generate and mask every provider credential; keep files under <code>$RUNNER_TEMP</code> at mode <code>0600</code> and clean with <code>always()</code>.</li><li>[ ] Do not expose credentials through command lines, step outputs, summaries, provider logs, browser traces, or uploaded artifacts.</li><li>[ ] Upload only redacted test reports and image metadata required for diagnosis. Keep the issue&#39;s screenshots, GIFs, and benchmark evidence on the pull request rather than in the repository.</li><li>[ ] Document the tested image digests, provider versions, trigger, and commit SHA in the Actions summary so a release result is reproducible.</li></ul><h2 id="primary-source-register" tabindex="-1">Primary-source register <a class="header-anchor" href="#primary-source-register" aria-label="Permalink to &quot;Primary-source register&quot;">​</a></h2><ul><li>OIDC harness: <a href="https://github.com/panva/node-oidc-provider/tree/v9.11.3" target="_blank" rel="noreferrer"><code>oidc-provider</code> v9.11.3</a></li><li>Pocket ID: <a href="https://pocket-id.org/docs/setup/installation" target="_blank" rel="noreferrer">installation</a>, <a href="https://pocket-id.org/docs/configuration/environment-variables" target="_blank" rel="noreferrer">environment</a>, <a href="https://pocket-id.org/docs/guides/oidc-client-authentication" target="_blank" rel="noreferrer">OIDC client authentication</a>, <a href="https://pocket-id.org/docs/configuration/allowed-groups" target="_blank" rel="noreferrer">allowed groups</a>, and <a href="https://github.com/pocket-id/pocket-id/tree/v2.14.0" target="_blank" rel="noreferrer">v2.14.0 tagged source</a></li><li>Authentik: <a href="https://docs.goauthentik.io/install-config/install/docker-compose" target="_blank" rel="noreferrer">Docker Compose installation</a>, <a href="https://docs.goauthentik.io/sys-mgmt/ops/monitoring" target="_blank" rel="noreferrer">monitoring</a>, <a href="https://docs.goauthentik.io/add-secure-apps/providers/oauth2/" target="_blank" rel="noreferrer">OAuth2/OIDC provider</a>, <a href="https://docs.goauthentik.io/customize/blueprints/" target="_blank" rel="noreferrer">blueprints</a>, and <a href="https://github.com/goauthentik/authentik/tree/version/2026.8.0" target="_blank" rel="noreferrer">2026.8.0 tagged source</a></li><li>Container: <a href="https://docs.docker.com/build/building/multi-stage/" target="_blank" rel="noreferrer">Docker multi-stage builds</a>, <a href="https://docs.docker.com/build/building/best-practices/" target="_blank" rel="noreferrer">Docker build practices</a>, <a href="https://docs.docker.com/reference/compose-file/services/" target="_blank" rel="noreferrer">Compose services</a>, and <a href="https://bun.com/guides/ecosystem/docker" target="_blank" rel="noreferrer">Bun&#39;s Docker guide</a></li><li>CI: <a href="https://docs.github.com/en/actions/reference/workflows-and-actions/events-that-trigger-workflows" target="_blank" rel="noreferrer">GitHub Actions events</a>, <a href="https://docs.github.com/en/actions/how-tos/write-workflows/choose-what-workflows-do/use-secrets" target="_blank" rel="noreferrer">secrets</a>, and <a href="https://docs.github.com/en/actions/reference/workflows-and-actions/deployments-and-environments" target="_blank" rel="noreferrer">environments</a></li></ul>',74)])])}const g=t(i,[["render",n]]);export{p as __pageData,g as default};
